def split_csv(line):
    fields = []
    i = 0

    while i < len(line):
        # Parse one field
        if line[i] == '"':
            # Quoted field
            field = ""
            i += 1
            while i < len(line):
                if line[i] == '"':
                    i += 1
                    if i < len(line) and line[i] == '"':
                        # Doubled quote - represents one quote character
                        field += '"'
                        i += 1
                    else:
                        # End of quoted field
                        break
                else:
                    field += line[i]
                    i += 1
            else:
                # Reached end of line without closing quote
                return None

            # After closing quote, must be comma or end of line
            if i < len(line) and line[i] != ',':
                return None
            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma
        else:
            # Unquoted field
            field = ""
            while i < len(line) and line[i] != ',':
                if line[i] == '"':
                    # Unquoted field must not contain double quotes
                    return None
                field += line[i]
                i += 1
            fields.append(field)
            if i < len(line):
                i += 1  # Skip the comma

    return fields

